import json, sys
data = json.load(sys.stdin)
print('Phase:', data['status']['phase'])
print('Init Container Statuses:')
for cs in data['status'].get('initContainerStatuses', []):
    print(f'  {cs[\"name\"]}: ready={cs[\"ready\"]}, restartCount={cs[\"restartCount\"]}')
    if cs.get('state', {}).get('waiting'):
        print(f'    waiting: {cs[\"state\"][\"waiting\"]}')
    if cs.get('lastState', {}).get('terminated'):
        print(f'    lastState: {cs[\"lastState\"][\"terminated\"]}')
print('Container Statuses:')
for cs in data['status'].get('containerStatuses', []):
